body.query:
query Occurrence($key: ID!, $defaultChecklistKey: ID) {
  occurrence(key: $key) {
    key
    coordinates
    organismName
    lastCrawled
    countryCode
    stateProvince
    locality
    eventDate
    typeStatus
    occurrenceStatus
    references
    issues
    issuesWithSeverity {
      id
      severity
    }
    nonTaxonomicIssues
    basisOfRecord
    dynamicProperties
    institutionKey
    collectionKey
    isInCluster
    volatile {
      globe(sphere: false, land: false, graticule: false) {
        svg
        lat
        lon
      }
      features {
        isSpecimen
        isTreament
        isSequenced
        isClustered
        isSamplingEvent
        firstIIIF
      }
    }
    datasetKey
    datasetTitle
    publishingOrgKey
    publisherTitle
    dataset {
      citation {
        text
      }
    }
    institutionCode

    earliestEonOrLowestEonothem
    earliestEraOrLowestErathem
    earliestPeriodOrLowestSystem
    earliestEpochOrLowestSeries
    earliestAgeOrLowestStage
    lowestBiostratigraphicZone

    group
    formation
    member
    bed

    extensions {
      audubon
      amplification
      germplasmAccession
      germplasmMeasurementScore
      germplasmMeasurementTrait
      germplasmMeasurementTrial
      identification
      identifier
      image
      measurementOrFact
      multimedia
      reference
      eolReference
      resourceRelationship
      cloning
      gelImage
      loan
      materialSample
      permit
      preparation
      preservation
      extendedMeasurementOrFact
      chronometricAge
      dnaDerivedData
    }

    # Interpreted (sanitised) sequences, used to show a sanitised view of the DNA-derived-data
    # extension's verbatim dna_sequence. For a single sequence we pair positionally; for several
    # the DNA block validates the raw sequences to pair them (order isn't guaranteed).
    nucleotideSequences {
      nucleotideSequenceID
      sequence
      targetGene {
        concept
      }
    }

    gadm

    stillImageCount
    movingImageCount
    soundCount
    stillImages {
      ...OccurrenceMediaDetails
    }
    sounds {
      ...OccurrenceMediaDetails
    }
    movingImages {
      ...OccurrenceMediaDetails
    }

    verbatimScientificName
    classification(checklistKey: $defaultChecklistKey) {
      checklistKey
      meta {
        mainIndex {
          clbDatasetKey
        }
      }
      usage {
        rank
        name
        key
      }
      acceptedUsage {
        key
        name
        taxon {
          label
          classification {
            key: taxonID
            rank: taxonRank
            name: scientificName
          }
        }
      }
      taxonMatch {
        usage {
          name
          key
          canonicalName
          formattedName
        }
        synonym
      }
      classification {
        key
        rank
        name
      }
      issues
      hasTaxonIssues
      iucnRedListCategoryCode
    }
    classifications {
      meta {
        mainIndex {
          clbDatasetKey
          datasetTitle
        }
      }
      checklistKey
      usage {
        rank
        name
        key
      }
      acceptedUsage {
        key
        name
      }
      taxonMatch {
        usage {
          name
          key
          canonicalName
          formattedName
        }
        synonym
      }
      classification {
        key
        rank
        name
      }
      issues
    }
    primaryImage {
      identifier
    }
    terms {
      ...OccurrenceTerm
    }
    scientificName
    recordedByIDs {
      type
      value
    }
    identifiedByIDs {
      type
      value
    }
  }
}

fragment OccurrenceMediaDetails on MultimediaItem {
  title
  type
  format
  identifier
  created
  creator
  license
  publisher
  references
  rightsHolder
  description
  originalImage: thumbor
  thumbor(height: 800)
  smallThumbnail: thumbor(height: 800)
}

fragment OccurrenceTerm on Term {
  simpleName
  verbatim
  value
  htmlValue
  remarks
  issues
}
